#!/usr/bin/env bash
# Makes COSMIC's own theme (Files, Terminal, Settings, panel, dock ...) follow the JellyFace palette.
#   cosmic-theme.sh apply [scheme.json]   write the dark theme from the scheme (default: the live JellyFace scheme)
#   cosmic-theme.sh reset                 give COSMIC its own stock theme back (restores the originals)
#   cosmic-theme.sh status
# The theme files are generated by COSMIC's own theme library (tools/cosmic-theme) into a temporary folder; only keys
# that your installed COSMIC already uses are copied into ~/.config/cosmic. The stock files under /usr are never touched.
set -uo pipefail
. "$(dirname "$0")/lib.sh"

COSMIC_CFG="${XDG_CONFIG_HOME:-$HOME/.config}/cosmic"
SYS="/usr/share/cosmic"
DIRS=(com.system76.CosmicTheme.Dark com.system76.CosmicTheme.Dark.Builder)
TOOL="$JF_ROOT/tools/cosmic-theme/target/release/jellyface-cosmic-theme"
SCHEME="${XDG_STATE_HOME:-$HOME/.local/state}/caelestia/scheme.json"

case "${1:-status}" in
    apply)
        scheme="${2:-$SCHEME}"
        [ -x "$TOOL" ] || die "theme tool not built. Run: jellyface build"
        [ -f "$scheme" ] || die "no scheme at $scheme"
        tmp="$(mktemp -d)"; trap 'rm -rf -- "$tmp"' EXIT
        XDG_CONFIG_HOME="$tmp" "$TOOL" "$scheme" >/dev/null || die "theme tool failed"
        for d in "${DIRS[@]}"; do
            [ -d "$tmp/cosmic/$d/v1" ] || die "tool wrote no $d/v1 (COSMIC format mismatch?); nothing changed"
        done
        for d in "${DIRS[@]}"; do
            sys_track "$COSMIC_CFG/$d"
            mkdir -p "$COSMIC_CFG/$d/v1"
            for f in "$tmp/cosmic/$d/v1/"*; do
                k="$(basename "$f")"
                [ -e "$SYS/$d/v1/$k" ] && cp "$f" "$COSMIC_CFG/$d/v1/$k"   # only keys your COSMIC already knows
            done
        done
        log "COSMIC theme updated from $(basename "$(dirname "$scheme")")/$(basename "$scheme")"
        ;;
    reset)
        for d in "${DIRS[@]}"; do
            path="$COSMIC_CFG/$d"
            backup="$(awk -F'\t' -v p="$path" '$1==p{print $2}' "$JF_MANIFEST" 2>/dev/null | head -1)"
            if [ "$backup" = "(new)" ]; then rm -rf -- "$path"
            elif [ -n "$backup" ] && [ -e "$backup" ]; then rm -rf -- "$path"; cp -a "$backup" "$path"
            else log "$d: nothing to reset"; fi
        done
        log "COSMIC's own theme restored"
        ;;
    status)
        n=$(ls "$COSMIC_CFG/${DIRS[0]}/v1" 2>/dev/null | wc -l)
        [ "$n" -gt 0 ] && log "COSMIC theme: JellyFace-generated ($n theme keys in $COSMIC_CFG/${DIRS[0]}/v1)" || log "COSMIC theme: stock"
        ;;
    *) echo "usage: cosmic-theme.sh apply|reset|status" >&2; exit 2 ;;
esac
